import {DOMPurify,jsPDF,QRCode,opentype,PDFDocument} from './vendor/tools.js?v=0.2.1';
import {PT_MM} from './geometry.js?v=0.2.1';
export const NS='http://www.w3.org/2000/svg';
export const fonts=new Map();
function normalizeNamespace(el){const c=document.createElementNS(NS,el.localName);for(const a of el.attributes)c.setAttribute(a.name,a.value);for(const child of el.childNodes)c.append(child.nodeType===1?normalizeNamespace(child):child.cloneNode(true));return c;}
export function svgElement(tag,attrs={}){const el=document.createElementNS(NS,tag);for(const[k,v]of Object.entries(attrs))el.setAttribute(k,v);return el;}
export function cleanSVG(text){const cleaned=DOMPurify.sanitize(text,{USE_PROFILES:{svg:true,svgFilters:true},ADD_TAGS:['style'],ADD_ATTR:['data-object','data-name','data-readable','data-font','data-locked','data-hidden','data-group','data-native','data-size','data-leading','data-weight'],FORBID_TAGS:['foreignObject','script','animate','animateTransform','set']});const doc=new DOMParser().parseFromString(cleaned,'image/svg+xml');if(doc.querySelector('parsererror')||doc.documentElement.localName!=='svg')throw Error('Не удалось прочитать SVG');const svg=doc.documentElement;for(const el of svg.querySelectorAll('*')){for(const a of [...el.attributes]){if(a.name.startsWith('on'))el.removeAttribute(a.name);if(/^(?:href|xlink:href)$/i.test(a.name)&&!a.value.startsWith('#')&&!a.value.startsWith('data:image/')&&!a.value.startsWith('data:font/'))el.removeAttribute(a.name);if(/url\(\s*['"]?(?:https?:|\/\/)/i.test(a.value))el.removeAttribute(a.name);}}for(const style of svg.querySelectorAll('style')){style.textContent=style.textContent.replace(/@import[^;]+;/gi,'').replace(/url\(\s*(['"]?)(?!data:|#)[^)]+\)/gi,'none');}return svg;}
function lengthMM(value,fallback){const m=String(value||'').match(/^([\d.]+)(mm|cm|in|pt|px)?$/);if(!m)return fallback;const factors={mm:1,cm:10,in:25.4,pt:PT_MM,px:25.4/96};return Number(m[1])*(factors[m[2]||'px']);}
export function readSVG(text,name='SVG'){const svg=cleanSVG(text),vb=(svg.getAttribute('viewBox')||'').trim().split(/[ ,]+/).map(Number);const w=lengthMM(svg.getAttribute('width'),vb[2]?vb[2]*25.4/96:210),h=lengthMM(svg.getAttribute('height'),vb[3]?vb[3]*25.4/96:297);if(!(w>0&&h>0&&w<=5000&&h<=5000))throw Error('Некорректный размер страницы');if(!svg.hasAttribute('viewBox'))svg.setAttribute('viewBox',`0 0 ${w*96/25.4} ${h*96/25.4}`);svg.setAttribute('x','0');svg.setAttribute('y','0');svg.setAttribute('width',w);svg.setAttribute('height',h);svg.setAttribute('overflow','hidden');return{name,w,h,markup:svg.outerHTML,source:'SVG',guides:[]};}
function b64(bytes){let result='';for(let i=0;i<bytes.length;i+=8192)result+=String.fromCharCode(...bytes.subarray(i,i+8192));return btoa(result);}
export function registerFont(data,family){const buffer=data instanceof Uint8Array?data:new Uint8Array(data);const parsed=opentype.parse(buffer.buffer.slice(buffer.byteOffset,buffer.byteOffset+buffer.byteLength));fonts.set(family,{parsed,data:b64(buffer)});return parsed;}
export async function loadDefaultFont(){const bundled=[{file:'atelier-sans.ttf',family:'Atelier Sans'},{file:'atelier-sans-bold.ttf',family:'Atelier Sans Bold'}];try{const r=await fetch(new URL('./fonts/manrope.json',import.meta.url));if(r.ok)bundled.push(...await r.json());}catch{}await Promise.all(bundled.map(async({file,family})=>{const r=await fetch(new URL('./fonts/'+file,import.meta.url));if(!r.ok)throw Error('Не удалось загрузить '+family);const bytes=new Uint8Array(await r.arrayBuffer());registerFont(bytes,family);fonts.get(family).builtin=true;const face=await new FontFace(family,bytes).load();document.fonts.add(face);}));}
function supportGroups(gfx,OPS){const run=gfx.executeOpTree;gfx._svgGroups=[];gfx.executeOpTree=function(tree){for(const op of tree){if(op.fnId===OPS.beginGroup){const group=this.svgFactory.createElement('svg:g');group.setAttribute('opacity',this.current.fillAlpha);this.svg.append(group);this._svgGroups.push({parent:this.svg,clip:this.current.clipGroup});this.svg=group;this.tgrp=null;this.current.clipGroup=null;}else if(op.fnId===OPS.endGroup){const saved=this._svgGroups.pop();if(saved){this.svg=saved.parent;this.current.clipGroup=saved.clip;this.tgrp=null;}}else run.call(this,[op]);}};}
export async function readPDF(bytes,name,onProgress){const pdfjs=window.pdfjsLib;pdfjs.GlobalWorkerOptions.workerSrc=new URL('./vendor/pdf.worker.min.js',import.meta.url).href;const pdf=await pdfjs.getDocument({data:bytes.slice(),isEvalSupported:false,fontExtraProperties:true,useSystemFonts:true,disableAutoFetch:true}).promise;let boxDoc;try{boxDoc=await PDFDocument.load(bytes,{ignoreEncryption:true,updateMetadata:false});}catch{}const pages=[];for(let n=1;n<=pdf.numPages;n++){onProgress?.(`Открываю страницу ${n} из ${pdf.numPages}…`);const page=await pdf.getPage(n),viewport=page.getViewport({scale:1}),op=await page.getOperatorList(),gfx=new pdfjs.SVGGraphics(page.commonObjs,page.objs,true);gfx.embedFonts=true;supportGroups(gfx,pdfjs.OPS);const svg=normalizeNamespace(await gfx.getSVG(op,viewport)),text=await page.getTextContent();svg.setAttribute('xmlns',NS);const items=text.items.filter(i=>i.str?.trim());for(const original of [...svg.querySelectorAll('text')]){const spans=[...original.querySelectorAll('tspan')];if(spans.length>1){for(const span of spans){const row=original.cloneNode(false);row.append(span.cloneNode(true));original.before(row);}original.remove();}}const texts=[...svg.querySelectorAll('text')];let idx=0;for(const el of texts){const tspans=[...el.querySelectorAll('tspan')];const take=Math.max(1,tspans.length);const read=items.slice(idx,idx+take);el.setAttribute('data-readable',read.map(i=>i.str).join('\n'));idx+=take;const fn=tspans[0]?.getAttribute('font-family')||'';const f=gfx.embeddedFonts[fn];el.setAttribute('data-font',f?.name?.replace(/^[A-Z]{6}\+/,'')||'Встроенный шрифт');el.setAttribute('data-pdf-text','true');}
for(const [family,f]of Object.entries(gfx.embeddedFonts)){if(f.data){try{registerFont(f.data,family);}catch{}}}
const w=viewport.width*PT_MM,h=viewport.height*PT_MM;svg.setAttribute('width',w);svg.setAttribute('height',h);svg.setAttribute('x','0');svg.setAttribute('y','0');svg.setAttribute('overflow','hidden');let trim=null;const bp=boxDoc?.getPage(n-1);if(bp){const b=bp.getTrimBox(),media=bp.getCropBox();trim={x:(b.x-media.x)*PT_MM,y:(media.y+media.height-b.y-b.height)*PT_MM,width:b.width*PT_MM,height:b.height*PT_MM};}pages.push({name:`${name} · ${n}`,w,h,markup:svg.outerHTML,source:'PDF / AI · RGB',trim,guides:[]});}return pages;}
export function getFontsForProject(){return [...fonts].filter(([,v])=>!v.builtin).map(([family,v])=>({family,data:v.data}));}
export function restoreFonts(list){for(const f of list||[]){try{registerFont(Uint8Array.from(atob(f.data),c=>c.charCodeAt(0)),f.family);const face=new FontFace(f.family,`url(data:font/ttf;base64,${f.data})`);face.load().then(ff=>document.fonts.add(ff)).catch(()=>{});}catch{}}}
export function addFontStyles(svg){let defs=svg.querySelector('defs');if(!defs){defs=svgElement('defs');svg.prepend(defs);}const style=svgElement('style');style.textContent=[...fonts].map(([family,v])=>`@font-face{font-family:"${(family==='Atelier Sans Bold'?'Atelier Sans':family).replace(/["\\]/g,'')}";font-weight:${family.endsWith(' Bold')?700:400};src:url(data:font/ttf;base64,${v.data})}`).join('\n');defs.append(style);}
export function textToOutlines(svg){const warnings=new Set();for(const text of [...svg.querySelectorAll('text')]){const spans=text.querySelectorAll('tspan').length?[...text.querySelectorAll('tspan')]:[text],group=svgElement('g');for(const a of text.attributes)if(!['x','y','dx','dy','font-family','font-size','text-anchor'].includes(a.name))group.setAttribute(a.name,a.value);for(const span of spans){const family=(span.getAttribute('font-family')||text.getAttribute('font-family')||'Atelier Sans').replace(/["']/g,'').split(',')[0].trim();const weight=span.getAttribute('font-weight')||text.getAttribute('font-weight');let font=fonts.get((weight==='bold'||Number(weight)>=600)&&fonts.has(family+' Bold')?family+' Bold':family)?.parsed;if(!font){font=fonts.get('Atelier Sans')?.parsed;warnings.add(family);}if(!font)throw Error('Шрифт для экспорта не загружен');const size=parseFloat(span.getAttribute('font-size')||text.getAttribute('font-size')||'5');const xs=(span.getAttribute('x')||text.getAttribute('x')||'0').trim().split(/[ ,]+/).map(Number),ys=(span.getAttribute('y')||text.getAttribute('y')||'0').trim().split(/[ ,]+/).map(Number);const str=span.textContent||'';const anchor=span.getAttribute('text-anchor')||text.getAttribute('text-anchor');const advance=font.getAdvanceWidth(str,size);let x=xs[0]||0,y=ys[0]||0;if(anchor==='middle')x-=advance/2;else if(anchor==='end')x-=advance;let d='';if(xs.length>1){[...str].forEach((char,i)=>{d+=font.getPath(char,xs[i]??x,ys[i]??y,size).toPathData(5);});}else{d=font.getPath(str,x,y,size).toPathData(5);}const path=svgElement('path',{d});for(const attr of ['fill','stroke','stroke-width','opacity','fill-opacity','transform']){if(span!==text&&span.hasAttribute(attr))path.setAttribute(attr,span.getAttribute(attr));}group.append(path);}text.replaceWith(group);}return[...warnings];}
let lastDownloadURL;export function download(data,name,type){if(lastDownloadURL)URL.revokeObjectURL(lastDownloadURL);const url=URL.createObjectURL(data instanceof Blob?data:new Blob([data],{type}));lastDownloadURL=url;let a=document.getElementById('download-ready');if(!a){a=document.createElement('a');a.id='download-ready';a.className='download-ready';document.body.append(a);}a.href=url;a.download=name;a.textContent='Скачать '+name+' ↓';a.title='Если скачивание не началось, нажмите здесь';a.click();}
export async function exportPDF(pages,makeSVG,name){let doc;const warnings=new Set();for(let i=0;i<pages.length;i++){const p=pages[i],orientation=p.w>p.h?'landscape':'portrait';if(!doc)doc=new jsPDF({unit:'mm',format:[p.w,p.h],orientation,compress:true,precision:6});else doc.addPage([p.w,p.h],orientation);const svg=makeSVG(i);textToOutlines(svg).forEach(x=>warnings.add(x));svg.setAttribute('width',p.w*72/25.4);svg.setAttribute('height',p.h*72/25.4);document.body.append(svg);try{await doc.svg(svg,{x:0,y:0,width:p.w,height:p.h});}finally{svg.remove();}}
const out=await PDFDocument.load(doc.output('arraybuffer'));pages.forEach((p,i)=>{if(p.trim){const b=p.trim;out.getPage(i).setTrimBox(b.x/PT_MM,(p.h-b.y-b.height)/PT_MM,b.width/PT_MM,b.height/PT_MM);}});const bytes=await out.save();const checked=await PDFDocument.load(bytes);if(checked.getPageCount()!==pages.length)throw Error('Ошибка числа страниц PDF');checked.getPages().forEach((p,i)=>{if(Math.abs(p.getWidth()*PT_MM-pages[i].w)>.02||Math.abs(p.getHeight()*PT_MM-pages[i].h)>.02)throw Error('Не совпали размеры экспортированного PDF');});download(bytes,name+'.pdf','application/pdf');return[...warnings];}
export async function qrSVG(value,size){const code=await QRCode.toString(value,{type:'svg',margin:4,errorCorrectionLevel:'M',color:{dark:'#000000',light:'#ffffff'}});const svg=cleanSVG(code);svg.setAttribute('width',size);svg.setAttribute('height',size);return svg;}
